// Around the league: every matchup, and one game opened up.
import {matchupDetail,median} from '../../league.js';
import {S} from '../state.js';
import {chance,empty,esc,fmt,league,leagueOptions,ordinal,pageHead,playerChip,pname,projectionNote,record,signed,teamCell} from '../core.js';
import {currentLeagueOutlook,leagueGate} from './league-outlook.js';

export function lineupsView(o,g,by){
 const detail=matchupDetail({league:league(),players:S.data.players,projections:S.data.projections[S.data.week],games:S.data.games,rosterIds:g.teams});if(!detail)return '';
 const [a,b]=detail.sides,teams=g.teams.map(id=>by.get(id));
 const when=p=>{const game=p.game,where=game?.opponent?`${game.home?'vs':'@'} ${game.opponent}`:'';return p.state==='live'?`<span class="lu-clock">${esc(game.detail||'Live')}</span> ${esc(where)}`:p.state==='done'?`Final ${esc(where)}`:p.state==='bye'?'Bye':p.state==='pre'?esc([game.detail,where].filter(Boolean).join(' · ')):''};
 const player=(p,flip)=>p.id?`<div class="lu-player ${flip?'flip':''} lu-${p.state}">${playerChip(p.id,`<div class="muted small">${esc(S.data.players[p.id].position||'')} · ${esc(S.data.players[p.id].team||'FA')}${S.data.players[p.id].injury_status?` · <span class="attention">${esc(S.data.players[p.id].injury_status)}</span>`:''}</div><div class="lu-when small">${when(p)}</div>`)}</div>`:`<div class="lu-player ${flip?'flip':''} lu-empty"><span class="muted">Empty</span></div>`;
 // Before kickoff the number that matters is the projection; once he has played it is the points.
 const started=p=>p.state==='live'||p.state==='done'||p.state==='bye',points=(p,other,flip)=>{if(!p.id)return `<div class="lu-score ${flip?'flip':''}"><strong class="muted">—</strong></div>`;const diff=p.projection===null?null:p.points-p.projection,won=started(p)&&started(other)&&p.points>other.points;
  return `<div class="lu-score ${flip?'flip':''} ${won?'won':started(p)&&started(other)&&other.id?'lost':''}"><strong class="${started(p)?'':'pending'}">${started(p)?fmt(p.points,2):fmt(p.projection)}</strong><small>${p.state==='live'?`heading for ${fmt(p.heading)}`:p.state==='done'&&diff!==null?`<span class="${diff>=2?'gain':diff<=-2?'attention':''}">${signed(diff)}</span> vs ${fmt(p.projection)} proj.`:p.state==='bye'?'no game':'projected'}</small></div>`};
 const row=(x,y)=>`<div class="lu-row">${player(x,false)}${points(x,y,false)}<div class="lu-slot">${esc(x.label||y.label)}</div>${points(y,x,true)}${player(y,true)}</div>`;
 const none={id:null,points:0,projection:null,heading:0,state:'empty',label:'BN'},bench=Array.from({length:Math.max(a.bench.length,b.bench.length)},(_,i)=>row(a.bench[i]||{...none,label:b.bench[i].label},b.bench[i]||{...none,label:a.bench[i].label}));
 return `<div class="panel lineups"><div class="lu-head"><strong>${esc(teams[0].team)}</strong><span>STARTERS</span><strong>${esc(teams[1].team)}</strong></div>${a.starters.map((x,i)=>row(x,b.starters[i])).join('')}<div class="lu-row lu-total"><div class="lu-player"><span class="muted small">Projected before kickoff ${fmt(a.projection)}</span></div><div class="lu-score"><strong>${fmt(a.points,2)}</strong><small>heading for ${fmt(a.heading)}</small></div><div class="lu-slot">TOTAL</div><div class="lu-score flip"><strong>${fmt(b.points,2)}</strong><small>heading for ${fmt(b.heading)}</small></div><div class="lu-player flip"><span class="muted small">Projected before kickoff ${fmt(b.projection)}</span></div></div><div class="lu-head lu-bench-head"><span class="muted small">${fmt(a.benchPoints)} on the bench</span><span>BENCH</span><span class="muted small">${fmt(b.benchPoints)} on the bench</span></div>${bench.join('')}</div>`;
}
export function scoreboardPage(){
 const l=league(),head=pageHead('Around the league','Who is winning every matchup this week, how safe it is, and what it does to the standings.',`<div class="filters"><select class="select" aria-label="Analysis league" id="analysis-league">${leagueOptions(l?.league_id)}</select><button class="secondary" id="refresh" ${S.busy?'disabled':''}>${S.busy?'Refreshing…':'↻ Refresh'}</button></div>`)+projectionNote(),gate=leagueGate(head);if(gate)return gate;
 const o=currentLeagueOutlook(),by=new Map(o.rows.map(r=>[r.rosterId,r])),teams=o.rows.filter(r=>r.live);
 if(!teams.length)return head+empty('No matchups this week','Sleeper has not posted this week’s matchups for this league.');
 const sorted=[...teams].sort((a,b)=>b.live.mean-a.live.mean),medianLine=median(teams.map(r=>r.live.mean));
 const total=c=>c.pre+c.live+c.done,all=teams.reduce((s,r)=>({pre:s.pre+r.live.counts.pre,live:s.live+r.live.counts.live,done:s.done+r.live.counts.done}),{pre:0,live:0,done:0});
 // One meter everywhere: finished, on the field now, still to come.
 const meter=(c,label)=>`<span class="lineup-meter" role="img" aria-label="${esc(label)}: ${c.done} finished, ${c.live} playing, ${c.pre} to play">${[['done',c.done],['live',c.live],['pre',c.pre]].filter(([,n])=>n).map(([k,n])=>`<i class="meter-${k}" style="flex:${n}"></i>`).join('')}</span>`;
 const leader=[...teams].sort((a,b)=>b.live.points-a.live.points)[0],closest=[...o.live.games].sort((a,b)=>Math.abs(a.chance-.5)-Math.abs(b.chance-.5))[0];
 const tiles=(o.live.known?'':'<p class="data-alert" role="status">NFL game status is unavailable, so which starters have finished is a guess. Scores are still live.</p>')+`<div class="league-tiles">
  <div class="league-tile"><div class="eyebrow">WEEK ${S.data.week} ${o.live.complete?'IS FINAL':all.live?'IS LIVE':o.live.started?'SO FAR':'HAS NOT STARTED'}</div><strong>${total(all)?Math.round(all.done/total(all)*100):0}%<small> of starters done</small></strong>${meter(all,'The league’s starters')}</div>
  <div class="league-tile"><div class="eyebrow">${o.live.started?'TOP SCORE':'TOP PROJECTION'}</div><strong>${o.live.started?fmt(leader.live.points,2):fmt(sorted[0].live.mean)}</strong><span class="muted small">${esc((o.live.started?leader:sorted[0]).team)}</span></div>
  ${closest?`<div class="league-tile"><div class="eyebrow">TIGHTEST MATCHUP</div><strong>${Math.round(Math.max(closest.chance,1-closest.chance)*100)}–${Math.round(Math.min(closest.chance,1-closest.chance)*100)}</strong><span class="muted small">${closest.teams.map(id=>esc(by.get(id)?.team)).join(' vs ')}</span></div>`:''}
  ${o.shape.medianGame?`<div class="league-tile"><div class="eyebrow">MEDIAN LINE</div><strong>${fmt(medianLine)}</strong><span class="muted small">Heading above it earns a second win</span></div>`:''}</div>`;
 // How a matchup stands, in a word. An upset is the lower-ranked team being the likelier winner.
 const verdict=(a,b,p)=>{const sure=Math.max(p,1-p),ahead=p>=.5?a:b,behind=p>=.5?b:a;
  if(!a.live.share&&!b.live.share)return ['final',`Final · ${ahead.team} won`];
  if(sure<.6)return ['close','Toss-up'];
  if(ahead.powerRank-behind.powerRank>=3)return ['upset',`Upset brewing · ${ahead.team}`];
  return [sure>=.9?'safe':'lean',`${sure>=.9?'All but over':sure>=.75?'Comfortable':'Leaning'} · ${ahead.team}`]};
 const side=(r,p,other,flip,hero)=>{const ahead=p>.5||p===.5&&!flip;return `<div class="game-side ${flip?'flip':''} ${ahead?'ahead':'behind'}"><div class="game-name"><strong>${esc(r.team)}</strong>${r.mine?'<span class="pill you">YOU</span>':''}</div><div class="game-sub">${record(r)}${hero?` · ${ordinal(r.powerRank)} in power`:''} · playoffs ${chance(r.odds.playoff,o)}</div></div><div class="game-score ${flip?'flip':''} ${ahead?'ahead':'behind'}"><strong>${fmt(r.live.points,2)}</strong><small>${r.live.share>0?`→ ${fmt(r.live.mean)}`:'final'}</small></div>`};
 const foot=(r,flip)=>`<div class="game-foot ${flip?'flip':''}">${meter(r.live.counts,r.team)}<span>${total(r.live.counts)-r.live.counts.done?`${total(r.live.counts)-r.live.counts.done} left`:'done'}${r.live.top?` · ${esc(pname(r.live.top.id))} ${fmt(r.live.top.points)}`:''}</span>${o.shape.medianGame?`<span class="median-mark ${r.live.mean>=medianLine?'up':'down'}">${r.live.mean>=medianLine?'▲':'▼'} median</span>`:''}</div>`;
 const game=(g,hero=false,open=false)=>{const [a,b]=g.teams.map(id=>by.get(id));const over=!a?.live?.share&&!b?.live?.share,sure=p=>over?Math.round(p*100):Math.min(99,Math.max(1,Math.round(p*100)));if(!a?.live||!b?.live)return '';const me=a.mine?a:b.mine?b:null,mineP=me===a?g.chance:1-g.chance,[tone,label]=verdict(a,b,g.chance),live=a.live.counts.live+b.live.counts.live;
  return `<article class="game ${hero?'hero':''} ${me?'mine':''} ${open?'':'openable'}" aria-label="${esc(a.team)} against ${esc(b.team)}" ${open?'':`data-open-game="${g.teams.join(':')}"`}><header class="game-head"><span class="game-tag tag-${tone}">${esc(label)}</span><span class="game-head-right">${live?`<span class="pill live">LIVE · ${live} playing</span>`:''}${open?'':`<button class="inline-btn" data-open-game="${g.teams.join(':')}">Lineups →</button>`}</span></header><div class="game-body">${side(a,g.chance,b,false,hero)}${side(b,1-g.chance,a,true,hero)}</div><div class="game-odds"><b>${sure(g.chance)}%</b><span class="game-bar ${me?(mineP>=.5?'winning':'losing'):g.chance<.5?'favors-right':''} ${me===b?'mine-right':''}" role="img" aria-label="${esc(a.team)} ${Math.round(g.chance*100)}% to win, ${esc(b.team)} ${Math.round((1-g.chance)*100)}%"><i style="flex:${Math.max(.03,g.chance)}"></i><i style="flex:${Math.max(.03,1-g.chance)}"></i></span><b>${sure(1-g.chance)}%</b></div><div class="game-feet">${foot(a,false)}${foot(b,true)}</div></article>`};
 const opened=S.openGame&&o.live.games.find(g=>g.teams.join(':')===S.openGame);
 if(opened)return head+`<div class="board-bar"><button class="secondary" data-close-game>← All matchups</button><span class="muted small">Points so far, and what each player was projected for or is heading for</span></div>`+game(opened,true,true)+lineupsView(o,opened,by)+`<p class="watch-footnote">A live player’s “heading for” is his points plus his pregame projection for the part of the game still to play. Bench points do not count.</p>`;
 const mineGame=o.live.games.find(g=>g.teams.some(id=>by.get(id)?.mine)),others=o.live.games.filter(g=>g!==mineGame).sort((a,b)=>Math.abs(a.chance-.5)-Math.abs(b.chance-.5));
 const legend=`<div class="meter-legend" aria-hidden="true"><span>Win chance and where each score is heading (→)</span><span><i class="meter-done"></i>Finished</span><span><i class="meter-live"></i>Playing now</span><span><i class="meter-pre"></i>Yet to play</span></div>`;
 const cards=(mineGame?`<h2 class="board-title">Your matchup</h2>${game(mineGame,true)}`:'')+(others.length?`<div class="board-bar"><h2 class="board-title">${mineGame?'The rest of the league':'This week’s matchups'}</h2><span class="muted small">Closest first</span></div><div class="game-grid">${others.map(g=>game(g)).join('')}</div>`:'')+legend;
 // The standings as they would read if every matchup ended the way it is heading.
 const result=r=>{const g=o.live.games.find(g=>g.teams.includes(r.rosterId));if(!g||!o.current)return null;const p=g.teams[0]===r.rosterId?g.chance:1-g.chance;return {p,win:p>.5,sure:Math.max(p,1-p)>=.75}};
 const table=[...o.rows].sort((a,b)=>b.wins+b.ties/2-(a.wins+a.ties/2)||b.pf-a.pf),tier=p=>p>=.7?'in':p>=.35?'bubble':'out';
 const standings=`<div class="panel table-wrap league-panel"><div class="section-bar"><div><h2>What it does to the standings</h2><p class="muted small">Through ${o.games?`week ${o.weeks.at(-1).week}`:'the preseason'}. The line is the playoff cut. <button class="inline-btn" data-nav="league">Full league outlook →</button></p></div></div><table class="league-table"><thead><tr><th scope="col">TEAM</th><th scope="col">RECORD</th>${o.current?'<th scope="col">THIS WEEK</th>':''}<th scope="col">POINTS FOR</th><th scope="col">PLAYOFFS</th></tr></thead><tbody>${table.map((r,i)=>{const w=result(r);return `<tr class="${i===o.shape.playoffTeams-1&&i<table.length-1?'playoff-cut':''} ${r.mine?'mine':''}">${teamCell({...r,team:`${i+1}. ${r.team}`})}<td class="num">${record(r)}</td>${o.current?`<td class="num">${w?`<span class="result-chip ${w.win?'win':'loss'} ${w.sure?'sure':''}" title="${Math.round(w.p*100)}% to win">${w.sure?'':'Leaning '}${w.win?'W':'L'}</span> <span class="muted small">${fmt(r.live?.points,1)}</span>`:'<span class="muted">Bye</span>'}</td>`:''}<td class="num">${fmt(r.pf)}</td><td><div class="odds odds-${tier(r.odds.playoff)}" title="Playoff odds for ${esc(r.team)}"><span class="odds-track"><i style="width:${Math.round(r.odds.playoff*100)}%"></i></span><strong>${chance(r.odds.playoff,o)}</strong></div></td></tr>`}).join('')}</tbody></table></div>`;
 return head+tiles+cards+standings+`<p class="watch-footnote">The arrow is the live score plus the pregame projection for the part of each game still to play. Win chances assume a full week swings about ${fmt(o.spread,0)} points and shrink that as starters finish.</p>`;
}
